--- a/gateway/proxy/stream_buffer.rs
+++ b/gateway/proxy/stream_buffer.rs
@@ -120,6 +120,22 @@ fn pump_loop(...) {
     // previously: write chunks as soon as available
+    // now: consult pacer to avoid egress bursts
+    if let Some(ref pacer) = ctx.egress_pacer {
+        pacer.await_permit().await?;
+    }
+
+    match next_chunk {
+        Some(chunk) => write_chunk(chunk).await?,
        None => break,
    }
+
+    // if write fails due to stall threshold, trigger fncall failsafe
+    if ctx.stall_duration > ctx.cfg.fncall_fail_threshold {
+        trigger_fncall_failsafe(&mut ctx).await?;
+    }
 }
